def proverb(*pieces, qualifier=None):
    if not pieces:
        return []

    lines = [
        f"For want of a {first} the {second} was lost."
        for first, second in zip(pieces, pieces[1:])
    ]

    last = pieces[0]
    if qualifier:
        last = f"{qualifier} {last}"
    lines.append(f"And all for the want of a {last}.")

    return lines

